// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"blockchain":{"slug":"blockchain","cat":"basics","en":"Blockchain","contentLocale":"es","term":"Blockchain (cadena de bloques)","aka":["cadena de bloques"],"short":"Una blockchain o cadena de bloques es un registro digital compartido en el que las transacciones se agrupan en bloques encadenados entre sí, de modo que cambiar un dato antiguo exigiría rehacer todos los bloques posteriores.","body":["Imagina un libro contable que no guarda un banco, sino miles de computadoras (nodos) repartidas por el mundo. Cada bloque contiene un lote de transacciones y una huella criptográfica (hash) del bloque anterior. Si alguien altera un bloque viejo, su hash cambia y la cadena deja de cuadrar, así que el resto de la red lo rechaza.",["Para decidir quién añade el siguiente bloque, cada red usa un mecanismo de consenso. ",["Bitcoin","bitcoin"]," usa ",["prueba de trabajo","proof-of-work"]," (minería) y ",["Ethereum","ethereum"]," usa ",["prueba de participación","proof-of-stake"]," (validadores con ETH en ",["staking","staking"],"). El resultado es un historial público que cualquiera puede consultar con un ",["explorador de bloques","block-explorer"],"."],"Para ti como usuario esto significa dos cosas: las transacciones confirmadas son prácticamente irreversibles y no hay un servicio de atención al cliente que pueda deshacer un envío a la dirección equivocada. Por eso conviene revisar red y dirección antes de cada retiro."],"example":"Supón que envías 0,05 BTC a un amigo. Tu transacción espera en la cola de la red hasta que un minero la incluye en un bloque. Bitcoin produce un bloque cada 10 minutos de media, así que tras 6 confirmaciones (unos 60 minutos) la mayoría de los exchanges dan el depósito por definitivo. Si en el bloque 3 alguien intentara borrar tu pago, tendría que rehacer ese bloque y los 3 siguientes más rápido que toda la red honesta, algo que en una red grande resulta carísimo.","mistakes":["Creer que la blockchain guarda tus monedas dentro de la app del exchange, cuando en realidad solo registra saldos asociados a direcciones.","Pensar que una transacción confirmada se puede cancelar o revertir pidiéndolo al soporte.","Suponer que todas las blockchains son iguales y enviar fondos por una red distinta a la que admite la dirección de destino."],"faq":[{"q":"¿Para qué sirve una blockchain?","a":"Sirve para llevar un registro de transacciones o datos que nadie puede modificar en solitario. Su uso más conocido son las criptomonedas, pero también se usa para tokens, contratos inteligentes y trazabilidad."},{"q":"¿Blockchain y Bitcoin son lo mismo?","a":"No. Bitcoin es una criptomoneda que funciona sobre su propia blockchain. Hay muchas otras blockchains, como Ethereum o Solana, con reglas distintas."}],"title":"¿Qué es una blockchain? Significado y cómo funciona","description":"Qué es una blockchain o cadena de bloques, cómo se encadenan los bloques y por qué las transacciones confirmadas no se pueden deshacer.","related":[["cryptocurrency","Criptomoneda","Una criptomoneda es un activo digital que se transfiere directamente entre usuarios sobre una blockchain, sin un banco central que lo emita ni un intermediario que apruebe cada pago."],["proof-of-work","Prueba de trabajo (proof of work, PoW)","La prueba de trabajo (PoW) es un mecanismo de consenso en el que los mineros gastan potencia de cálculo y electricidad para resolver un problema criptográfico y ganar el derecho a añadir el siguiente bloque."],["proof-of-stake","Prueba de participación (proof of stake, PoS)","La prueba de participación (PoS) es un mecanismo de consenso en el que los validadores bloquean monedas como garantía para proponer y confirmar bloques, y pueden perder parte de ellas si actúan de forma deshonesta."],["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."],["block-explorer","Explorador de bloques","Un explorador de bloques es un sitio o herramienta que te permite buscar y ver en tiempo real las transacciones, direcciones y bloques de una blockchain pública."]],"lesson":{"id":"E03","slug":"exchange-vs-wallet","ep":3,"title":"¿Dónde están mis monedas? Exchange vs billetera"},"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"trading-volume":{"slug":"trading-volume","cat":"trading","en":"Trading volume","contentLocale":"es","term":"Volumen de trading","aka":["volumen de negociación","volumen 24h","trading volume"],"short":"El volumen de trading es el valor total de un activo que se ha comprado y vendido en un periodo concreto, normalmente las últimas 24 horas.","body":[["El volumen suele mostrarse en dólares o en ",["USDT","usdt"],", o en unidades de la moneda. Cuando una página dice que ",["BTC","bitcoin"]," tuvo 20.000 millones de volumen en 24 horas, suma el valor de todas las operaciones casadas en ese periodo, ya sea en un exchange o en varios."],"Los traders usan el volumen para confirmar movimientos. Una ruptura de precio con volumen alto suele considerarse más sólida que una con volumen bajo. En los gráficos de velas, el volumen aparece como barras bajo cada vela.",["Ojo: el volumen no es lo mismo que la ",["liquidez","liquidity"],", y puede inflarse. Algunas plataformas han sido señaladas por ",["wash trading","wash-trading"],", operaciones ficticias que suben el volumen sin interés real. Además, el volumen de futuros suele ser varias veces mayor que el de spot, así que compara siempre el mismo tipo de mercado y fíjate también en el ",["interés abierto","open-interest"]," y en la profundidad del libro."]],"example":["Supón que en un día se negocian 1.200 ",["ETH","ethereum"]," a un precio medio de 3.000 USDT en el par ETH/USDT de un exchange. El volumen de 24 horas de ese par es 1.200 × 3.000 = 3,6 millones de USDT. Si al día siguiente el precio sube un 6 % pero solo se negocian 400 ETH, el volumen cae a unos 1,27 millones de USDT: la subida se produjo con mucha menos participación."],"mistakes":["Tomar el volumen de un exchange poco conocido como prueba de que el mercado es líquido.","Comparar el volumen de futuros de una moneda con el volumen spot de otra.","Pensar que volumen alto significa automáticamente que el precio subirá."],"faq":[{"q":"¿Qué indica un volumen de trading alto?","a":"Indica mucha actividad e interés en ese activo durante el periodo. No dice por sí solo si el precio subirá o bajará, pero ayuda a valorar la fuerza de un movimiento."},{"q":"¿El volumen de trading puede ser falso?","a":"Sí. Con wash trading una plataforma o un participante opera consigo mismo para inflar el volumen. Por eso conviene contrastarlo con la profundidad del libro y con datos de varias fuentes."}],"title":"¿Qué es el volumen de trading en cripto? Significado","description":"Qué mide el volumen de trading en 24 horas, cómo leerlo en el gráfico y por qué no siempre refleja liquidez real.","related":[["liquidity","Liquidez","La liquidez es la facilidad con la que puedes comprar o vender un activo rápidamente, en la cantidad que quieres, sin mover mucho su precio."],["market-capitalization","Capitalización de mercado (market cap)","La capitalización de mercado (market cap) de una criptomoneda es el precio de una unidad multiplicado por su suministro circulante, y sirve para comparar el tamaño de distintos proyectos."],["open-interest","Interés abierto","El interés abierto es el número o valor total de contratos de futuros u opciones que siguen abiertos en un momento dado y todavía no se han cerrado ni liquidado."],["wash-trading","Wash trading (operaciones ficticias)","El wash trading es comprar y vender el mismo activo a uno mismo, o entre cuentas coordinadas, para crear volumen o precios artificiales sin un cambio real de propietario."]],"lesson":null,"coin":null,"tool":"/coins","cta":false},"position-sizing":{"slug":"position-sizing","cat":"trading","en":"Position sizing","contentLocale":"es","term":"Tamaño de posición","aka":["position sizing","gestión del tamaño de posición","tamaño de la operación"],"short":"El tamaño de posición es la cantidad de capital que asignas a una operación, calculada para que, si toca tu stop loss, pierdas solo un porcentaje fijo de tu cuenta.","body":[["Muchos principiantes deciden cuánto comprar por intuición. Un método más sólido empieza al revés: primero decides cuánto estás dispuesto a perder si la operación sale mal, por ejemplo el 1 % de la cuenta, y luego calculas el tamaño según la distancia entre tu entrada y tu ",["stop loss","stop-loss"],"."],"La fórmula básica es: tamaño = riesgo en dinero / distancia al stop. Si el stop está lejos, la posición debe ser más pequeña; si está cerca, puede ser mayor. Así cada operación arriesga lo mismo, sin importar el activo.",["Con ",["apalancamiento","leverage"]," esto es aún más importante. El apalancamiento cambia cuánto margen bloqueas, pero no cuánto pierdes si el precio llega a tu stop: eso depende del tamaño nocional. Además, debes comprobar que el ",["precio de liquidación","liquidation-price"]," quede bastante más lejos que tu stop loss."]],"example":["Tienes una cuenta de 5.000 ",["USDT","usdt"]," y aceptas arriesgar el 1 %, es decir, 50 USDT por operación. Quieres comprar ",["ETH","ethereum"]," en 3.000 con stop loss en 2.850, una distancia de 150 USDT. El tamaño es 50 / 150 = 0,333 ETH, unos 1.000 USDT de valor nocional. Si usas apalancamiento 5x, bloqueas unos 200 USDT de margen, pero la pérdida al tocar el stop sigue siendo 50 USDT."],"mistakes":["Elegir el tamaño por el apalancamiento máximo disponible en lugar de por el riesgo aceptable.","Mover el stop loss más lejos tras abrir la posición sin reducir el tamaño.","Arriesgar el mismo número de monedas en activos con volatilidades muy distintas."],"faq":[{"q":"¿Qué porcentaje de la cuenta se arriesga por operación?","a":"Muchos traders usan entre el 0,5 % y el 2 % por operación como regla propia. Lo importante es que una racha de pérdidas no deje la cuenta inutilizable."},{"q":"¿El apalancamiento cambia el tamaño de posición?","a":"El apalancamiento solo cambia el margen que necesitas. El riesgo real depende del tamaño nocional y de la distancia al stop loss."}],"title":"¿Qué es el tamaño de posición? Cómo calcularlo","description":"Aprende a calcular el tamaño de posición según tu riesgo y tu stop loss, y por qué el apalancamiento no cambia la pérdida.","related":[["risk-reward-ratio","Relación riesgo-beneficio","La relación riesgo-beneficio compara cuánto puedes perder en una operación hasta tu stop loss con cuánto puedes ganar hasta tu take profit."],["stop-loss","Stop loss (orden de stop)","Un stop loss es una orden que cierra automáticamente tu posición cuando el precio llega a un nivel que has fijado, para limitar la pérdida si el mercado va en tu contra."],["leverage","Apalancamiento","El apalancamiento es usar capital prestado para abrir una posición mayor que tu margen, de modo que las ganancias y las pérdidas se multiplican en la misma proporción."],["liquidation","Liquidación","La liquidación es el cierre forzoso de una posición apalancada por parte del exchange cuando tu margen ya no cubre el margen de mantenimiento exigido."]],"lesson":{"id":"E16","slug":"position-sizing-basics","ep":16,"title":"Decide cuánto podrías perder antes de decidir cuánto comprar"},"coin":null,"tool":null,"cta":false},"funding-rate":{"slug":"funding-rate","cat":"derivatives","en":"Funding rate","contentLocale":"es","term":"Tasa de financiación (funding rate)","aka":["funding rate","tasa de fondeo","comisión de financiación","funding"],"short":"La tasa de financiación es un pago periódico entre traders largos y cortos de futuros perpetuos que mantiene el precio del contrato cerca del precio spot.","body":[["Cuando el perpetuo cotiza por encima del ",["índice spot","index-price"],", la tasa es positiva y los largos pagan a los cortos. Cuando cotiza por debajo, la tasa es negativa y los cortos pagan a los largos. El exchange no se queda con este dinero: pasa directamente de un grupo de traders a otro."],["La tasa se aplica sobre el valor nocional de tu posición, no sobre tu margen. Muchos exchanges la liquidan cada 8 horas, pero algunos pares y plataformas usan intervalos de 1, 2 o 4 horas, y cada exchange fija topes distintos. Solo pagas o cobras si tienes la posición abierta en el momento de la ",["liquidación","liquidation"],"."],["Una tasa muy positiva indica que hay mucha demanda de largos apalancados; una muy negativa, exceso de cortos. Los traders la usan como termómetro del sentimiento, y algunos hacen ",["arbitraje de tasa de financiación","funding-rate-arbitrage"],". Revisa la tasa prevista antes de abrir una posición que piensas mantener."]],"example":["Tienes un corto de 5 ",["ETH","ethereum"]," a 3.000 ",["USDT","usdt"],", un nocional de 15.000 USDT. La tasa es +0,03 % cada 8 horas, así que como corto cobras 15.000 × 0,03 % = 4,5 USDT por intervalo, 13,5 USDT al día. Si dos días después la tasa pasa a −0,02 %, empiezas a pagar 3 USDT por intervalo. En una semana, la tasa puede sumar o restar varias decenas de USDT a tu resultado."],"mistakes":["Calcular la tasa sobre el margen en lugar del valor nocional de la posición.","Cerrar justo después del momento de liquidación creyendo que se evita el pago.","Interpretar una tasa positiva como garantía de que el precio subirá."],"faq":[{"q":"¿Una tasa de financiación negativa es alcista?","a":"Indica que hay más presión de cortos. A veces precede a subidas por cierre de cortos, pero por sí sola no predice la dirección del precio."},{"q":"¿Cada cuánto se paga la tasa de financiación?","a":"Lo más habitual es cada 8 horas, pero algunos pares usan 1, 2 o 4 horas. Mira la especificación del contrato en tu exchange."},{"q":"¿Quién recibe la tasa de financiación?","a":"La reciben los traders del lado contrario. Si la tasa es positiva cobran los cortos; si es negativa cobran los largos."}],"title":"¿Qué es la tasa de financiación (funding rate)?","description":"Qué es la tasa de financiación de los perpetuos, quién paga a quién, cada cuánto se cobra y cómo calcular su coste.","related":[["perpetual-futures","Futuros perpetuos (perps)","Los futuros perpetuos son contratos de futuros sin fecha de vencimiento que siguen el precio spot gracias a pagos periódicos entre largos y cortos llamados tasa de financiación."],["funding-rate-arbitrage","Arbitraje de tasa de financiación","El arbitraje de tasa de financiación es una estrategia que combina una posición spot y una posición contraria en futuros perpetuos para cobrar la tasa de financiación sin exponerse a la dirección del precio."],["mark-price","Precio de marca","El precio de marca es un precio de referencia que calculan los exchanges de futuros a partir del índice spot y otros datos, y que usan para calcular la ganancia no realizada y las liquidaciones."],["index-price","Precio índice","El precio índice es el precio spot de referencia de un activo que calcula un exchange como media ponderada de los precios de varios exchanges spot."],["open-interest","Interés abierto","El interés abierto es el número o valor total de contratos de futuros u opciones que siguen abiertos en un momento dado y todavía no se han cerrado ni liquidado."]],"lesson":{"id":"E24","slug":"funding-fees-final","ep":24,"title":"¿Precio plano, saldo abajo? Termina el último nivel pensando en los costes"},"coin":null,"tool":"/funding-rates","cta":true},"defi":{"slug":"defi","cat":"defi","en":"DeFi (decentralized finance)","contentLocale":"es","term":"DeFi (finanzas descentralizadas)","aka":["finanzas descentralizadas","DeFi","decentralized finance"],"short":"DeFi, o finanzas descentralizadas, es el conjunto de servicios financieros, como intercambios, préstamos o rendimientos, que funcionan mediante contratos inteligentes en una blockchain sin un intermediario central.","body":[["En lugar de abrir una cuenta en una empresa, conectas tu ",["billetera no custodial","non-custodial-wallet"]," a una aplicación. Las reglas están en contratos inteligentes públicos: una ",["DEX","dex"]," como Uniswap intercambia tokens, un protocolo como Aave presta y toma prestado, y otros generan rendimientos o derivados."],"La DeFi tiene ventajas claras: acceso abierto, funcionamiento las 24 horas, transparencia de los contratos y control directo de tus fondos. También permite combinar protocolos, porque un token de un servicio puede usarse en otro.",["Los riesgos son distintos a los de un exchange: errores en los contratos, hackeos, oráculos manipulados, liquidaciones automáticas, ",["pérdida impermanente","impermanent-loss"]," y aprobaciones de tokens maliciosas. No hay atención al cliente que revierta una transacción, así que conviene empezar con montos pequeños y protocolos auditados y con historial."]],"example":["Tienes 1.000 ",["USDC","usdc"]," en tu ",["billetera","crypto-wallet"],". Depositas 600 USDC en un ",["protocolo de préstamos","defi-lending"]," y recibes un rendimiento variable, por ejemplo del 4 % anual, que equivaldría a unos 24 USDC en un año si la tasa se mantuviera. Con los otros 400 USDC compras ETH en una DEX, pagando una comisión de swap del 0,3 %, es decir 1,2 USDC, más el gas de la red. Todo ocurre sin registrarte en ninguna plataforma, solo firmando transacciones."],"mistakes":["Entrar en un protocolo solo por su rendimiento alto sin entender de dónde sale.","Firmar transacciones sin revisar aprobaciones ni montos.","Olvidar que necesitas el token nativo de la red, como ETH, para pagar el gas."],"faq":[{"q":"¿Qué diferencia hay entre DeFi y un exchange centralizado?","a":"En un exchange centralizado la empresa custodia tus fondos y ejecuta las operaciones. En DeFi operas desde tu propia billetera con contratos inteligentes públicos."},{"q":"¿Es seguro usar DeFi?","a":"Depende del protocolo y de tus hábitos. Hay riesgos técnicos como errores en contratos y riesgos de usuario como el phishing, por eso conviene usar protocolos con historial y montos que puedas permitirte perder."}],"title":"¿Qué es DeFi? Finanzas descentralizadas explicadas","description":"Qué es DeFi, cómo funcionan las finanzas descentralizadas con contratos inteligentes y qué riesgos debes conocer.","related":[["dex","Exchange descentralizado (DEX)","Un exchange descentralizado (DEX) es una plataforma de intercambio de cripto que funciona con contratos inteligentes, donde operas directamente desde tu billetera sin entregar la custodia de tus fondos."],["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."],["total-value-locked","Valor total bloqueado (TVL)","El valor total bloqueado (TVL) es el valor en dólares de todos los activos depositados en un protocolo DeFi o en una blockchain en un momento dado."],["defi-lending","Préstamos DeFi","Los préstamos DeFi son protocolos en los que depositas cripto para ganar intereses o la usas como garantía para pedir prestados otros tokens, con reglas aplicadas automáticamente por contratos inteligentes."],["liquidity-pool","Pool de liquidez","Un pool de liquidez es un contrato inteligente que guarda reservas de dos o más tokens para que otros usuarios puedan intercambiarlos, a cambio de comisiones que reciben quienes aportaron esos fondos."]],"lesson":null,"coin":{"slug":"aave","name":"Aave","symbol":"AAVE"},"tool":null,"cta":false},"cross-chain-bridge":{"slug":"cross-chain-bridge","cat":"defi","en":"Cross-chain bridge","contentLocale":"es","term":"Puente entre cadenas (cross-chain bridge)","aka":["bridge","puente cross-chain","puente de blockchain","puente"],"short":"Un puente entre cadenas es un protocolo que permite mover el valor de un token de una blockchain a otra, normalmente bloqueándolo en el origen y emitiendo una representación equivalente en el destino.","body":[["Las blockchains no se comunican de forma nativa. Un puente vigila la red de origen y, cuando bloqueas o quemas tokens allí, libera o crea tokens en la red de destino. Algunos usan validadores externos, otros pools de ",["liquidez","liquidity"]," en ambas redes y otros pruebas criptográficas."],["Existen puentes oficiales de redes de ",["capa 2","layer-2"],", como los de Arbitrum u Optimism, y puentes de terceros que conectan muchas redes. Los tiempos varían de minutos a días, y retirar desde algunas capas 2 optimistas por el puente nativo puede tardar alrededor de una semana."],"Los puentes concentran grandes sumas en contratos y han sido objetivo de algunos de los hackeos más grandes de cripto. Además, el token que recibes puede ser una versión envuelta que no es la misma que la nativa de la red. Muchas veces es más sencillo y barato retirar desde un exchange directamente a la red que necesitas."],"example":["Tienes 1.000 ",["USDC","usdc"]," en ",["Ethereum","ethereum"]," y quieres usarlos en Arbitrum. Con un puente, pagas el gas de Ethereum, por ejemplo 6 USDC, más una comisión del puente de 1 USDC, y recibes 993 USDC en Arbitrum minutos después. Como alternativa, si tus USDC están en un exchange, podrías retirarlos directamente por la red Arbitrum pagando la ",["comisión de retiro","withdrawal-fee"],", por ejemplo 0,5 USDC, sin pasar por ningún puente."],"mistakes":["Usar un puente encontrado en un anuncio o mensaje sin verificar el sitio oficial.","No comprobar si el token recibido es la versión nativa o una versión envuelta que los exchanges no aceptan.","Enviar fondos por un puente sin tener gas en la red de destino para usarlos después."],"faq":[{"q":"¿Es seguro usar un puente entre cadenas?","a":"Depende del diseño y de la trayectoria del puente. Han sufrido hackeos importantes, por eso conviene usar puentes conocidos y no dejar fondos en ellos más de lo necesario."},{"q":"¿Cuánto tarda un bridge?","a":"Desde minutos hasta varios días, según el puente y la dirección. Las retiradas por los puentes nativos de algunas capas 2 optimistas tardan unos 7 días."}],"title":"¿Qué es un bridge (puente entre cadenas)?","description":"Qué es un puente entre cadenas, cómo mueve tokens entre blockchains y qué riesgos tiene frente a retirar desde un exchange.","related":[["wrapped-token","Token envuelto (wrapped token)","Un token envuelto es un token que representa otro activo en una blockchain distinta o en otro estándar, respaldado uno a uno por el activo original que queda bloqueado o custodiado."],["layer-2","Capa 2 (layer 2, L2)","Una capa 2 (layer 2 o L2) es una red construida sobre una blockchain base que procesa transacciones fuera de ella y publica los resultados en la cadena principal para abaratar comisiones sin renunciar del todo a su seguridad."],["blockchain-network","Red de depósito (selección de red)","La red de depósito es la blockchain por la que se envía una criptomoneda, y elegirla bien es clave porque el mismo token, como USDT, existe en varias redes que no se comunican entre sí."],["smart-contract","Contrato inteligente (smart contract)","Un contrato inteligente (smart contract) es un programa publicado en una blockchain que se ejecuta automáticamente según reglas predefinidas cuando alguien interactúa con él, sin que un intermediario tenga que aprobarlo."]],"lesson":{"id":"E09","slug":"pre-transfer-checklist","ep":9,"title":"Antes de transferir: no adivines ninguno de estos puntos"},"coin":null,"tool":null,"cta":false},"stablecoin":{"slug":"stablecoin","cat":"stablecoins","en":"Stablecoin","contentLocale":"es","term":"Stablecoin (moneda estable)","aka":["moneda estable","criptomoneda estable","stablecoins"],"short":"Una stablecoin es una criptomoneda diseñada para mantener un valor estable frente a un activo de referencia, normalmente el dólar estadounidense, gracias a reservas, garantías en cripto u otros mecanismos.","body":[["Hay tres grandes modelos. Las respaldadas por reservas en dinero fiat y activos como letras del Tesoro, como ",["USDT","usdt"],", emitida por Tether, y ",["USDC","usdc"],", emitida por Circle. Las respaldadas por cripto sobrecolateralizada, como DAI. Y las sintéticas o algorítmicas, que usan estrategias de ",["cobertura","hedging"]," o incentivos de mercado."],["En los exchanges, las stablecoins son la moneda base de la mayoría de pares y de los ",["futuros perpetuos","perpetual-futures"],". También se usan para enviar valor entre exchanges, para pagos internacionales y como refugio temporal frente a la ",["volatilidad","volatility"],"."],["Estable no significa sin riesgo. Una stablecoin puede perder su paridad (",["depeg","depeg"],") por dudas sobre sus reservas, problemas de un banco custodio o fallos de su mecanismo. Además, los emisores centralizados pueden congelar direcciones. La regulación también varía: en la Unión Europea, MiCA aplica reglas a las stablecoins desde el 30 de junio de 2024."]],"example":"Vendes 0,2 BTC a 65.000 USDT y obtienes 13.000 USDT para esperar fuera del mercado. Una semana después, BTC baja a 60.000 USDT y vuelves a comprar: con 13.000 USDT obtienes unos 0,2167 BTC, sin contar comisiones. Durante esa semana, tu saldo en USDT se mantuvo cerca de 13.000 dólares, aunque estuvo expuesto al riesgo del emisor y del exchange donde lo guardabas.","mistakes":["Tratar una stablecoin como si fuera un depósito bancario con garantía pública.","Enviar una stablecoin por una red distinta a la que admite el destino.","Confiar en stablecoins con rendimientos muy altos sin entender de dónde salen."],"faq":[{"q":"¿Las stablecoins siempre valen 1 dólar?","a":"Están diseñadas para acercarse a 1 dólar, pero en momentos de tensión pueden cotizar por encima o por debajo."},{"q":"¿Cuál es la diferencia entre USDT y USDC?","a":"Las dos son stablecoins en dólares respaldadas por reservas. USDT la emite Tether y USDC la emite Circle, con distintas políticas de reservas, informes y presencia por red."}],"title":"¿Qué es una stablecoin y cómo mantiene su valor?","description":"Qué es una stablecoin, qué tipos existen como USDT, USDC o DAI y por qué pueden perder su paridad con el dólar.","related":[["usdt","USDT (Tether)","USDT es la stablecoin emitida por Tether que busca mantener un valor de 1 dólar estadounidense y que es la moneda base más usada en los exchanges de cripto."],["usdc","USDC (USD Coin)","USDC es una stablecoin emitida por Circle que busca mantener un valor de 1 dólar estadounidense y está respaldada por reservas en efectivo y activos de corto plazo del Tesoro de EE. UU."],["depeg","Depeg (pérdida de paridad)","Un depeg es cuando una stablecoin u otro activo vinculado pierde su paridad y cotiza claramente por encima o por debajo del valor que debería mantener, por ejemplo 1 dólar."],["crypto-backed-stablecoin","Stablecoin respaldada por criptomonedas","Una stablecoin respaldada por criptomonedas es una moneda estable que se emite depositando otras criptomonedas como colateral, normalmente por un valor mayor al de las monedas creadas."],["synthetic-dollar","Dólar sintético (stablecoin delta neutral)","Un dólar sintético es una stablecoin que mantiene su valor combinando criptoactivos en spot con posiciones cortas en futuros perpetuos, de modo que las subidas y bajadas se compensan."]],"lesson":{"id":"E02","slug":"is-usdt-a-dollar","ep":2,"title":"¿Es USDT un dólar? ¿Por qué se usa tanto al comprar cripto?"},"coin":{"slug":"tether","name":"Tether","symbol":"USDT"},"tool":null,"cta":false}});
